-- Arbeitsrecht Berufsbildung > Soziale gesellschaftliche Themen > Arbeitsschutz > Gefährdungsbeurteilung
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein IT-Betrieb eine Gefährdungsbeurteilung für Arbeitsplätze durchführen?', 2, '[{"text": "Ja", "correct": true, "because": "Pflicht gemäß § 5 Arbeitsschutzgesetz (ArbSchG)"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Gefährdungsbeurteilung in einem IT-Betrieb physische Gefahren wie Bildschirmarbeit einschließen?', 2, '[{"text": "Ja", "correct": true, "because": "Bildschirmarbeit birgt ergonomische Risiken"}, {"text": "Nein", "correct": false, "because": "Physische Gefahren sind relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Gefährdungsbeurteilung in einem IT-Betrieb nur für Hardwarewartung relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Sie umfasst alle Arbeitsbereiche"}, {"text": "Ja", "correct": false, "because": "Nicht auf Hardwarewartung beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen psychische Belastungen wie Stress in der Gefährdungsbeurteilung eines IT-Betriebs berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Psychische Gefährdungen sind Teil des ArbSchG"}, {"text": "Nein", "correct": false, "because": "Pflicht seit 2013"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb die Gefährdungsbeurteilung extern delegieren?', 2, '[{"text": "Ja", "correct": true, "because": "Externe Experten dürfen unterstützen"}, {"text": "Nein", "correct": false, "because": "Delegation ist zulässig"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz verpflichtet einen IT-Betrieb zur Gefährdungsbeurteilung?', 2, '[{"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": true, "because": "ArbSchG § 5 regelt die Pflicht"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}, {"text": "GmbHG", "correct": false, "because": "Regelt GmbH"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Gefährdungsbeurteilung in einem IT-Betrieb?', 3, '[{"text": "Schutz der Mitarbeitergesundheit", "correct": true, "because": "ArbSchG schützt Beschäftigte"}, {"text": "Erhöhung der Produktivität", "correct": false, "because": "Nebenprodukt, nicht Hauptziel"}, {"text": "Reduzierung von Steuern", "correct": false, "because": "Kein Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gefährdung muss ein IT-Betrieb bei der Beurteilung berücksichtigen?', 3, '[{"text": "Ergonomische Risiken bei Bildschirmarbeit", "correct": true, "because": "Relevante IT-Gefährdung"}, {"text": "Wetterbedingungen", "correct": false, "because": "Wenig Einfluss in IT"}, {"text": "Kundenzufriedenheit", "correct": false, "because": "Kein Arbeitsschutzthema"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist für die Durchführung der Gefährdungsbeurteilung in einem IT-Betrieb verantwortlich?', 2, '[{"text": "Der Arbeitgeber", "correct": true, "because": "ArbSchG § 5 legt Verantwortung beim Arbeitgeber"}, {"text": "Die Mitarbeiter", "correct": false, "because": "Mitarbeiter unterstützen nur"}, {"text": "Die IHK", "correct": false, "because": "IHK hat keine Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme folgt auf die Gefährdungsbeurteilung in einem IT-Betrieb?', 3, '[{"text": "Umsetzung von Schutzmaßnahmen", "correct": true, "because": "Maßnahmen schützen Beschäftigte"}, {"text": "Erhöhung der Arbeitszeit", "correct": false, "because": "Kein Schutzmaßnahme"}, {"text": "Reduzierung der Gehälter", "correct": false, "because": "Irrelevant"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Gefährdungen muss ein IT-Betrieb in der Gefährdungsbeurteilung berücksichtigen?', 4, '[{"text": "Ergonomische Risiken", "correct": true, "because": "Bildschirmarbeit birgt Risiken"}, {"text": "Psychische Belastungen", "correct": true, "because": "Stress ist relevant"}, {"text": "Wetterbedingungen", "correct": false, "because": "Wenig Einfluss in IT"}, {"text": "Elektrische Gefahren", "correct": true, "because": "Hardwarewartung birgt Risiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Gefährdungsbeurteilung einem IT-Betrieb?', 3, '[{"text": "Schutz der Mitarbeitergesundheit", "correct": true, "because": "Primäres Ziel"}, {"text": "Reduzierung von Arbeitsausfällen", "correct": true, "because": "Gesundheit fördert Produktivität"}, {"text": "Erhöhung der Steuerlast", "correct": false, "because": "Kein Vorteil"}, {"text": "Erfüllung gesetzlicher Pflichten", "correct": true, "because": "ArbSchG wird eingehalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte umfasst die Gefährdungsbeurteilung in einem IT-Betrieb?', 4, '[{"text": "Identifikation von Gefährdungen", "correct": true, "because": "Erster Schritt"}, {"text": "Bewertung der Risiken", "correct": true, "because": "Risiken werden analysiert"}, {"text": "Erhöhung der Arbeitszeit", "correct": false, "because": "Kein Schritt"}, {"text": "Festlegung von Schutzmaßnahmen", "correct": true, "because": "Maßnahmen werden geplant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken könnten in einem IT-Betrieb durch die Gefährdungsbeurteilung identifiziert werden?', 3, '[{"text": "Augenbelastung durch Bildschirme", "correct": true, "because": "Ergonomisches Risiko"}, {"text": "Stress durch Deadlines", "correct": true, "because": "Psychische Belastung"}, {"text": "Geringere Produktivität", "correct": false, "because": "Kein Risiko, sondern Folge"}, {"text": "Stromausfall bei Servern", "correct": true, "because": "Technisches Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die Gefährdungsbeurteilung eines IT-Betriebs von einem Produktionsbetrieb?', 3, '[{"text": "IT fokussiert ergonomische Risiken", "correct": true, "because": "Bildschirmarbeit zentral"}, {"text": "Produktion hat mehr physische Gefahren", "correct": true, "because": "Maschinenrisiken"}, {"text": "IT hat keine psychischen Belastungen", "correct": false, "because": "Stress ist relevant"}, {"text": "IT hat höhere Anforderungen", "correct": true, "because": "Technische Komplexität"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Gefährdungsbeurteilung ist im IT-Betrieb gesetzlich vorgeschrieben. b) Sie ist nur für physische Gefahren relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gesetzlich ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Psychische Belastungen müssen in der Gefährdungsbeurteilung eines IT-Betriebs berücksichtigt werden. b) Der Arbeitgeber ist für die Durchführung verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Psychische Belastungen und Arbeitgeberpflicht"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Gefährdungsbeurteilung schützt die Gesundheit der Mitarbeiter in einem IT-Betrieb. b) Sie kann komplett an Mitarbeiter delegiert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutz ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ergonomische Risiken sind Teil der Gefährdungsbeurteilung eines IT-Betriebs. b) Wetterbedingungen sind ein Hauptrisiko in der IT.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergonomie ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Gefährdungsbeurteilung führt zu Schutzmaßnahmen in einem IT-Betrieb. b) Sie ist nur für große Betriebe vorgeschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutzmaßnahmen ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

